// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface IcdSearchOut {
  code_system: "ICD-11" | "ICD-10";
  release_label: string;
  items: IcdSearchItemOut[];
}

export interface IcdSearchItemOut {
  /** A category's code; a block's id; a chapter's number */
  code: string;
  kind: "chapter" | "block" | "category";
  title: string;
  uri: string | null;
  chapter: string | null;
  parent_code: string | null;
  depth: number;
  is_leaf: boolean;
  /** An "other specified" or "unspecified" category: prefer a specific one */
  is_residual: boolean;
  /** The block or category above, to tell similar titles apart */
  parent_title: string | null;
}

export interface IcdBrowseOut {
  code_system: "ICD-11" | "ICD-10";
  release_label: string;
  /** The node whose children these are (null: the chapters) */
  parent: IcdEntryOut | null;
  items: IcdEntryOut[];
}

export interface IcdEntryOut {
  /** A category's code; a block's id; a chapter's number */
  code: string;
  kind: "chapter" | "block" | "category";
  title: string;
  uri: string | null;
  chapter: string | null;
  parent_code: string | null;
  depth: number;
  is_leaf: boolean;
  /** An "other specified" or "unspecified" category: prefer a specific one */
  is_residual: boolean;
}

export interface IcdDetailOut {
  /** A category's code; a block's id; a chapter's number */
  code: string;
  kind: "chapter" | "block" | "category";
  title: string;
  uri: string | null;
  chapter: string | null;
  parent_code: string | null;
  depth: number;
  is_leaf: boolean;
  /** An "other specified" or "unspecified" category: prefer a specific one */
  is_residual: boolean;
  code_system: "ICD-11" | "ICD-10";
  release_label: string;
  /** Chapter first, down to the parent */
  ancestors: IcdAncestorOut[];
  children: IcdEntryOut[];
}

export interface IcdAncestorOut {
  code: string;
  kind: "chapter" | "block" | "category";
  title: string;
  uri: string | null;
}

export interface IcdReleasesOut {
  /** The classification doctors code in (setting icd_coding_system) */
  coding_system: "ICD-11" | "ICD-10";
  releases: IcdReleaseOut[];
  /** The attribution the ICD-11 licence requires on screens and reports that use it */
  icd11_citation: string;
}

export interface IcdReleaseOut {
  release_id: number;
  code_system: "ICD-11" | "ICD-10";
  /** e.g. "2026-01" (ICD-11) or "2019" (ICD-10) */
  release_label: string;
  language: string;
  /** Bundled: shipped with the product (ICD-11); Imported: loaded by the hospital (its licensed ICD-10, or a newer ICD-11) */
  source: "Bundled" | "Imported";
  source_file: string | null;
  source_sha256: string | null;
  /** The licence the list is used under; show it where the list is used */
  licence_note: string;
  /** Codable categories */
  code_count: number;
  /** The list the picker searches and new codes are checked against */
  is_active: boolean;
  loaded_by: number | null;
  loaded_by_name: string | null;
  loaded_at: string;
  row_version: number;
}

/** ICD picker: search codes by code or words — GET /api/v1/icd/codes (who may call: any logged-in user). */
export function searchIcdCodes(query: { q: string; system?: "ICD-11" | "ICD-10" | null; limit?: number }): Promise<IcdSearchOut> {
  return api<IcdSearchOut>("GET", withQuery(`/icd/codes`, query), undefined);
}

/** ICD picker: browse chapters, blocks, categories — GET /api/v1/icd/browse (who may call: any logged-in user). */
export function browse(query?: { parent?: string | null; system?: "ICD-11" | "ICD-10" | null }): Promise<IcdBrowseOut> {
  return api<IcdBrowseOut>("GET", withQuery(`/icd/browse`, query), undefined);
}

/** One ICD code with its place in the tree — GET /api/v1/icd/codes/{code} (who may call: any logged-in user). */
export function detail(code: string, query?: { system?: "ICD-11" | "ICD-10" | null }): Promise<IcdDetailOut> {
  return api<IcdDetailOut>("GET", withQuery(`/icd/codes/${code}`, query), undefined);
}

/** The ICD code lists loaded — GET /api/v1/icd/releases (who may call: any logged-in user). */
export function releases(): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("GET", `/icd/releases`, undefined);
}
